void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    vec2 center = vec2(0.7, 0.4);
    vec2 centerPostion = iResolution.xy * center;
    float radius = 90.0;
    float thicknessFactor = 0.2;
    float distanceFromCenter = distance(fragCoord, centerPostion);

    float frequencyFactor = 0.06;
    float speed = 3.0;

    float maxValue = 1.0f/frequencyFactor;
    float d = sin(distanceFromCenter *frequencyFactor + iTime * speed)/frequencyFactor;
    d = clamp(0.0,d,d);

    d = maxValue - d;
    d = (thicknessFactor/frequencyFactor)/d;

    vec3 backgroundColor = vec3(0.0,0.0,0.0);
    vec3 circleColor = vec3(0.02,1.15,0.15);

    vec3 col = mix(backgroundColor, circleColor, d);

    fragColor = vec4(col,1.0);

}
